-- Optional: reconcile the manually created Neon table with the checked-in EF migration.
-- Preserves employee, task, attendance and login records.
BEGIN;
CREATE TABLE IF NOT EXISTS "DevicePushTokens" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "PushToken" varchar(256) NOT NULL,
    "Platform" varchar(16) NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_DevicePushTokens" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_DevicePushTokens_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_DevicePushTokens_PushToken" ON "DevicePushTokens" ("PushToken");
CREATE INDEX IF NOT EXISTS "IX_DevicePushTokens_UserId" ON "DevicePushTokens" ("UserId");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261028070000_AddDevicePushTokens', '10.0.12')
ON CONFLICT ("MigrationId") DO NOTHING;
COMMIT;
